local M = {}
function M.fixed(value)
    return string.format("%s%d.%04d", value < 0 and "-" or "", math.abs(value) // 10000, math.abs(value) % 10000)
end
function M.average(total, count)
    return M.fixed(10000 * total // count)
end
function M.cell(world, cell)
    return (cell // world.cols) .. "," .. (cell % world.cols)
end
function M.cells(world, cells)
    local values = {}
    for i, cell in ipairs(cells) do
        values[i] = M.cell(world, cell)
    end
    return table.concat(values, " ")
end
function M.grid(world, fields, separator)
    local lines = {}
    for row = 0, world.rows - 1 do
        local parts = {}
        for column = 0, world.cols - 1 do
            local cell = row * world.cols + column
            local state = world.state_index[cell + 1]
            parts[#parts + 1] = state and fields[state] or world.kinds:sub(cell + 1, cell + 1)
        end
        lines[#lines + 1] = table.concat(parts, separator)
    end
    return lines
end
function M.values(world, values)
    local fields = {}
    for i, value in ipairs(values) do
        fields[i] = M.fixed(value)
    end
    return M.grid(world, fields, " ")
end
function M.policy(world, policy)
    local fields = {}
    for i, action in ipairs(policy) do
        fields[i] = ("^>v<"):sub(action + 1, action + 1)
    end
    return M.grid(world, fields, "")
end
function M.q_rows(world, name, q, visits)
    local result = {}
    for state, cell in ipairs(world.states) do
        for action = 0, 3 do
            result[#result + 1] = table.concat({name, cell // world.cols, cell % world.cols, ("NESW"):sub(action + 1, action + 1), M.fixed(q[state][action + 1]), visits and visits[state][action + 1] or "-"}, ",")
        end
    end
    return result
end
function M.join_parts(parts)
    local lines = {}
    for i, part in ipairs(parts) do
        if i > 1 then
            lines[#lines + 1] = ""
        end
        for _, line in ipairs(part) do
            lines[#lines + 1] = line
        end
    end
    return lines
end
function M.write(name, lines)
    local file = assert(io.open("output/" .. name, "w"))
    for _, line in ipairs(lines) do
        file:write(line, "\n")
    end
    file:close()
end
return M

local dp = require("dynamic_programming")
local M = {}
function M.choose(generator, values, epsilon)
    if generator:draw() % 1000 < epsilon then
        return generator:draw() % 4
    end
    return dp.first_max(values)
end
function M.target(reward, terminal, value, gamma)
    return 10000 * reward + (terminal and 0 or gamma * value // 100)
end
function M.expected(values, epsilon)
    local total = 0
    for _, value in ipairs(values) do
        total = total + value
    end
    return (epsilon * total + 4 * (1000 - epsilon) * math.max(table.unpack(values))) // 4000
end
function M.update(values, action, target, alpha)
    values[action + 1] = values[action + 1] + alpha * (target - values[action + 1]) // 100
end
local Model = {}
Model.__index = Model
function M.model(states)
    local outcomes = {}
    for state = 1, states do
        outcomes[state] = {}
    end
    return setmetatable({outcomes = outcomes, pairs = {}}, Model)
end
function Model:record(state, action, reward, next_state)
    if not self.outcomes[state][action + 1] then
        self.pairs[#self.pairs + 1] = {state, action}
    end
    self.outcomes[state][action + 1] = {reward = reward, next_state = next_state}
end
function Model:plan(generator, q, gamma, alpha, steps)
    for _ = 1, steps do
        local pair = self.pairs[generator:draw() % #self.pairs + 1]
        local outcome = self.outcomes[pair[1]][pair[2] + 1]
        local value = outcome.next_state and math.max(table.unpack(q[outcome.next_state])) or 0
        M.update(q[pair[1]], pair[2], M.target(outcome.reward, not outcome.next_state, value, gamma), alpha)
    end
end
return M
